window.__kgRes("data/lessons/13-22.js",{"artifacts":[{"id":"artifact:13/22/skill-contract-reviewer","kind":"skill","name":"skill-contract-reviewer","text":"---\nname: skill-contract-reviewer\ndescription: Validate an Agent Skill package and choose the right instruction, capability, or lifecycle primitive before implementation.\nlicense: MIT\nmetadata:\n  lesson: \"22\"\n---\n\n# Skill contract reviewer\n\nUse this skill when a workflow is about to become a reusable agent artifact.\n\n1. Set `SKILL_ROOT` to the absolute directory containing this installed\n   `SKILL.md`. Do not assume the process working directory is the bundle.\n2. Set `TARGET_ROOT` to the absolute original workspace working directory and\n   resolve the proposed skill directory under that root.\n3. Read `$SKILL_ROOT/references/contract.md` and validate the portable\n   `SKILL.md` identity fields.\n4. Read `$SKILL_ROOT/references/decision-model.md` and separate repository\n   context, reusable method, external capability, lifecycle timing,\n   deterministic logic, and isolated delegation.\n5. Before execution, show the exact resolved argument vector. Run\n   `python3 \"$SKILL_ROOT/scripts/check_skill.py\" \"$TARGET_SKILL\"`, where\n   `TARGET_SKILL` is the absolute proposed skill directory under\n   `TARGET_ROOT`.\n6. Inspect the JSON report. Fix every error before discussing host-specific\n   extensions.\n7. Compare the proposed artifact with\n   `$SKILL_ROOT/assets/task-shapes.json` and return the smallest composable set\n   of primitives.\n\nDo not claim that a runtime extension is part of the portable contract. Do not treat a valid skill as permission to run scripts or access tools.\n\nReturn the validation report, the selected primitives, and one sentence\nexplaining each selection. Include execution evidence with the resolved script\npath, resolved target path, cwd, exact argv, and exit code. If the host cannot\nexpose one of those observations, mark it unverified instead of inventing it.\n"}],"code":[{"lang":"python","name":"main.py","text":"from __future__ import annotations\n\nimport json\nimport re\nimport tempfile\nfrom dataclasses import asdict, dataclass\nfrom pathlib import Path\nfrom typing import Any, Iterable\n\n\nCORE_FIELDS = {\n    \"name\",\n    \"description\",\n    \"license\",\n    \"compatibility\",\n    \"metadata\",\n    \"allowed-tools\",\n}\nNAME_PATTERN = re.compile(r\"^[a-z0-9]+(?:-[a-z0-9]+)*$\")\n\n\n@dataclass(frozen=True)\nclass ValidationIssue:\n    code: str\n    message: str\n\n\n@dataclass(frozen=True)\nclass SkillReport:\n    valid: bool\n    name: str | None\n    description: str | None\n    body: str\n    core_fields: tuple[str, ...]\n    runtime_extensions: tuple[str, ...]\n    issues: tuple[ValidationIssue, ...]\n\n    def to_dict(self) -> dict[str, Any]:\n        data = asdict(self)\n        data[\"issues\"] = [asdict(issue) for issue in self.issues]\n        return data\n\n\nclass FrontmatterSyntaxError(ValueError):\n    \"\"\"Raised when the lesson's deliberately small YAML subset is invalid.\"\"\"\n\n\ndef _decode_scalar(raw: str) -> str:\n    value = raw.strip()\n    if not value:\n        return \"\"\n    if value.startswith('\"'):\n        try:\n            decoded = json.loads(value)\n        except json.JSONDecodeError as error:\n            raise FrontmatterSyntaxError(f\"invalid quoted scalar: {error.msg}\") from error\n        if not isinstance(decoded, str):\n            raise FrontmatterSyntaxError(\"frontmatter scalars must be strings\")\n        return decoded\n    if value.startswith(\"'\"):\n        if len(value) < 2 or not value.endswith(\"'\"):\n            raise FrontmatterSyntaxError(\"unterminated single-quoted scalar\")\n        return value[1:-1].replace(\"''\", \"'\")\n    if value[0] in \"[{&*!\":\n        raise FrontmatterSyntaxError(\"unsupported YAML construct in portable subset\")\n    return value\n\n\ndef parse_frontmatter(text: str) -> tuple[dict[str, Any], str]:\n    \"\"\"Parse top-level scalars, block scalars, and a one-level metadata map.\"\"\"\n    lines = text.splitlines()\n    if not lines or lines[0] != \"---\":\n        raise FrontmatterSyntaxError(\"SKILL.md must begin with an exact --- line\")\n    try:\n        end = lines.index(\"---\", 1)\n    except ValueError as error:\n        raise FrontmatterSyntaxError(\"frontmatter needs a closing --- line\") from error\n\n    metadata: dict[str, Any] = {}\n    index = 1\n    while index < end:\n        line = lines[index]\n        if not line.strip() or line.lstrip().startswith(\"#\"):\n            index += 1\n            continue\n        if line[:1].isspace() or \":\" not in line:\n            raise FrontmatterSyntaxError(f\"malformed top-level line {index + 1}\")\n        key, raw_value = line.split(\":\", 1)\n        key = key.strip()\n        if not re.fullmatch(r\"[A-Za-z][A-Za-z0-9-]*\", key):\n            raise FrontmatterSyntaxError(f\"invalid field name {key!r}\")\n        if key in metadata:\n            raise FrontmatterSyntaxError(f\"duplicate field {key!r}\")\n\n        value = raw_value.strip()\n        if value in {\">\", \"|\"}:\n            block: list[str] = []\n            index += 1\n            while index < end and (not lines[index] or lines[index][:1].isspace()):\n                block.append(lines[index].lstrip())\n                index += 1\n            metadata[key] = (\" \" if value == \">\" else \"\\n\").join(block).strip()\n            continue\n        if key == \"metadata\" and not value:\n            nested: dict[str, str] = {}\n            index += 1\n            while index < end and (not lines[index] or lines[index][:1].isspace()):\n                nested_line = lines[index].strip()\n                if nested_line:\n                    if \":\" not in nested_line:\n                        raise FrontmatterSyntaxError(\n                            f\"malformed metadata line {index + 1}\"\n                        )\n                    nested_key, nested_value = nested_line.split(\":\", 1)\n                    nested_key = nested_key.strip()\n                    if nested_key in nested:\n                        raise FrontmatterSyntaxError(\n                            f\"duplicate metadata field {nested_key!r}\"\n                        )\n                    nested[nested_key] = _decode_scalar(nested_value)\n                index += 1\n            metadata[key] = nested\n            continue\n        metadata[key] = _decode_scalar(value)\n        index += 1\n\n    body = \"\\n\".join(lines[end + 1 :]).strip()\n    return metadata, body\n\n\ndef validate_skill_text(\n    text: str,\n    directory_name: str,\n    allowed_runtime_extensions: Iterable[str] = (),\n) -> SkillReport:\n    issues: list[ValidationIssue] = []\n    try:\n        fields, body = parse_frontmatter(text)\n    except FrontmatterSyntaxError as error:\n        issue = ValidationIssue(\"frontmatter-syntax\", str(error))\n        return SkillReport(False, None, None, \"\", (), (), (issue,))\n\n    name_value = fields.get(\"name\")\n    description_value = fields.get(\"description\")\n    name = name_value if isinstance(name_value, str) else None\n    description = description_value if isinstance(description_value, str) else None\n\n    if not name:\n        issues.append(ValidationIssue(\"name-required\", \"name must be a non-empty string\"))\n    elif len(name) > 64:\n        issues.append(ValidationIssue(\"name-too-long\", \"name must be at most 64 characters\"))\n    elif not NAME_PATTERN.fullmatch(name):\n        issues.append(\n            ValidationIssue(\n                \"name-format\",\n                \"name must use lowercase letters, digits, and single hyphens\",\n            )\n        )\n    elif name != directory_name:\n        issues.append(\n            ValidationIssue(\n                \"directory-mismatch\",\n                f\"name {name!r} must match directory {directory_name!r}\",\n            )\n        )\n\n    if not description or not description.strip():\n        issues.append(\n            ValidationIssue(\"description-required\", \"description must explain when to use the skill\")\n        )\n    elif len(description) > 1024:\n        issues.append(\n            ValidationIssue(\n                \"description-too-long\", \"description must be at most 1024 characters\"\n            )\n        )\n\n    if \"compatibility\" in fields:\n        compatibility = fields[\"compatibility\"]\n        if not isinstance(compatibility, str) or not compatibility.strip():\n            issues.append(\n                ValidationIssue(\n                    \"compatibility-empty\",\n                    \"compatibility must be a non-empty string when provided\",\n                )\n            )\n        elif len(compatibility) > 500:\n            issues.append(\n                ValidationIssue(\n                    \"compatibility-too-long\",\n                    \"compatibility must be at most 500 characters\",\n                )\n            )\n\n    if \"metadata\" in fields:\n        metadata = fields[\"metadata\"]\n        if not isinstance(metadata, dict) or not all(\n            isinstance(key, str) and isinstance(value, str)\n            for key, value in metadata.items()\n        ):\n            issues.append(\n                ValidationIssue(\n                    \"metadata-shape\",\n                    \"metadata must map string keys to string values\",\n                )\n            )\n\n    if \"allowed-tools\" in fields:\n        allowed_tools = fields[\"allowed-tools\"]\n        if not isinstance(allowed_tools, str) or not allowed_tools.strip():\n            issues.append(\n                ValidationIssue(\n                    \"allowed-tools-shape\",\n                    \"allowed-tools must be a non-empty space-separated string\",\n                )\n            )\n    if not body:\n        issues.append(ValidationIssue(\"body-required\", \"SKILL.md needs instruction content\"))\n\n    extension_names = sorted(set(fields) - CORE_FIELDS)\n    allowed = set(allowed_runtime_extensions)\n    for field in extension_names:\n        if field not in allowed:\n            issues.append(\n                ValidationIssue(\n                    \"unsupported-runtime-field\",\n                    f\"{field!r} is not part of the portable contract or this host policy\",\n                )\n            )\n\n    return SkillReport(\n        valid=not issues,\n        name=name,\n        description=description,\n        body=body,\n        core_fields=tuple(sorted(set(fields) & CORE_FIELDS)),\n        runtime_extensions=tuple(extension_names),\n        issues=tuple(issues),\n    )\n\n\n@dataclass(frozen=True)\nclass TaskShape:\n    repeatable_method: bool = False\n    repository_default: bool = False\n    external_capability: bool = False\n    lifecycle_event: bool = False\n    deterministic_logic: bool = False\n    isolated_delegation: bool = False\n\n\ndef select_primitives(task: TaskShape) -> tuple[str, ...]:\n    \"\"\"Select composable primitives by responsibility, not by product branding.\"\"\"\n    choices: list[str] = []\n    if task.repository_default:\n        choices.append(\"AGENTS.md\")\n    if task.repeatable_method:\n        choices.append(\"Agent Skill\")\n    if task.external_capability:\n        choices.append(\"MCP tool\")\n    if task.lifecycle_event:\n        choices.append(\"hook\")\n    if task.deterministic_logic:\n        choices.append(\"ordinary code\")\n    if task.isolated_delegation:\n        choices.append(\"subagent\")\n    return tuple(choices or [\"prompt\"])\n\n\ndef demo() -> None:\n    portable_example = \"\"\"---\nname: incident-summary\ndescription: Summarize an incident timeline when the user supplies event notes.\nmetadata:\n  owner: reliability\n---\n\n# Incident summary\n\nPreserve timestamps and separate observations from inferences.\n\"\"\"\n    host_extended_example = portable_example.replace(\n        \"description:\", \"user-invocable: true\\ndescription:\", 1\n    )\n    invalid_example = portable_example.replace(\n        \"name: incident-summary\", \"name: Incident_Summary\", 1\n    )\n    with tempfile.TemporaryDirectory(prefix=\"lesson-22-\") as temp_dir:\n        base = Path(temp_dir)\n        portable_dir = base / \"incident-summary\"\n        portable_dir.mkdir()\n        portable_path = portable_dir / \"SKILL.md\"\n        portable_path.write_text(portable_example, encoding=\"utf-8\")\n        portable_report = validate_skill_text(\n            portable_path.read_text(encoding=\"utf-8\"), portable_dir.name\n        )\n        host_report = validate_skill_text(\n            host_extended_example,\n            \"incident-summary\",\n            allowed_runtime_extensions={\"user-invocable\"},\n        )\n        invalid_report = validate_skill_text(\n            invalid_example, \"incident-summary\"\n        )\n\n    result = {\n        \"validation\": portable_report.to_dict(),\n        \"validation_cases\": {\n            \"portable_core\": portable_report.to_dict(),\n            \"host_extended\": host_report.to_dict(),\n            \"invalid_package\": invalid_report.to_dict(),\n        },\n        \"decision_examples\": {\n            \"one_off_rewrite\": select_primitives(TaskShape()),\n            \"repeatable_repo_workflow_with_api\": select_primitives(\n                TaskShape(\n                    repeatable_method=True,\n                    repository_default=True,\n                    external_capability=True,\n                )\n            ),\n            \"post_test_automation\": select_primitives(TaskShape(lifecycle_event=True)),\n            \"schema_normalization\": select_primitives(TaskShape(deterministic_logic=True)),\n            \"parallel_isolated_research\": select_primitives(\n                TaskShape(isolated_delegation=True)\n            ),\n        },\n    }\n    print(json.dumps(result, indent=2))\n\n\nif __name__ == \"__main__\":\n    demo()\n"},{"lang":"python","name":"tests/test_main.py","text":"\"\"\"Deterministic tests for the Lesson 22 skill contract lab.\"\"\"\n\nfrom __future__ import annotations\n\nimport sys\nimport importlib.util\nimport tempfile\nimport unittest\nfrom pathlib import Path\n\n\nsys.dont_write_bytecode = True\nsys.path.insert(0, str(Path(__file__).resolve().parents[1]))\n\nfrom main import TaskShape, parse_frontmatter, select_primitives, validate_skill_text\n\n\ndef skill_text(name: str = \"release-check\", description: str = \"Check a release.\") -> str:\n    return f\"\"\"---\nname: {name}\ndescription: {description}\n---\n\n# Release check\n\nVerify the version and produce a report.\n\"\"\"\n\n\nclass FrontmatterTests(unittest.TestCase):\n    def test_parses_folded_description_and_metadata(self) -> None:\n        text = \"\"\"---\nname: release-check\ndescription: >\n  Check a release when a maintainer\n  asks for a readiness report.\nmetadata:\n  owner: platform\n---\n# Instructions\nRun read-only checks.\n\"\"\"\n        fields, body = parse_frontmatter(text)\n        self.assertEqual(\n            fields[\"description\"],\n            \"Check a release when a maintainer asks for a readiness report.\",\n        )\n        self.assertEqual(fields[\"metadata\"], {\"owner\": \"platform\"})\n        self.assertIn(\"Run read-only checks\", body)\n\n    def test_rejects_duplicate_fields(self) -> None:\n        text = \"\"\"---\nname: release-check\nname: second-name\ndescription: Check a release.\n---\nBody\n\"\"\"\n        report = validate_skill_text(text, \"release-check\")\n        self.assertEqual(report.issues[0].code, \"frontmatter-syntax\")\n\n    def test_rejects_malformed_top_level_line(self) -> None:\n        text = skill_text().replace(\n            \"description: Check a release.\",\n            \"this is not yaml\\ndescription: Check a release.\",\n        )\n        report = validate_skill_text(text, \"release-check\")\n        self.assertEqual(report.issues[0].code, \"frontmatter-syntax\")\n\n\nclass ValidationTests(unittest.TestCase):\n    def test_accepts_valid_core_skill(self) -> None:\n        report = validate_skill_text(skill_text(), \"release-check\")\n        self.assertTrue(report.valid)\n        self.assertEqual(report.runtime_extensions, ())\n\n    def test_rejects_non_kebab_name(self) -> None:\n        report = validate_skill_text(skill_text(\"Release_Check\"), \"Release_Check\")\n        self.assertIn(\"name-format\", {issue.code for issue in report.issues})\n\n    def test_rejects_directory_mismatch(self) -> None:\n        report = validate_skill_text(skill_text(), \"different-directory\")\n        self.assertIn(\"directory-mismatch\", {issue.code for issue in report.issues})\n\n    def test_requires_description(self) -> None:\n        report = validate_skill_text(skill_text(description=\"\"), \"release-check\")\n        self.assertIn(\"description-required\", {issue.code for issue in report.issues})\n\n    def test_host_extension_requires_explicit_policy(self) -> None:\n        text = skill_text().replace(\"description:\", \"user-invocable: false\\ndescription:\")\n        portable = validate_skill_text(text, \"release-check\")\n        adapted = validate_skill_text(\n            text, \"release-check\", allowed_runtime_extensions={\"user-invocable\"}\n        )\n        self.assertFalse(portable.valid)\n        self.assertTrue(adapted.valid)\n        self.assertEqual(adapted.runtime_extensions, (\"user-invocable\",))\n\n    def test_compatibility_enforces_normative_length(self) -> None:\n        valid = skill_text().replace(\n            \"description:\", f\"compatibility: {'x' * 500}\\ndescription:\"\n        )\n        invalid = skill_text().replace(\n            \"description:\", f\"compatibility: {'x' * 501}\\ndescription:\"\n        )\n        self.assertTrue(validate_skill_text(valid, \"release-check\").valid)\n        report = validate_skill_text(invalid, \"release-check\")\n        self.assertIn(\"compatibility-too-long\", {issue.code for issue in report.issues})\n\n    def test_metadata_must_be_string_mapping(self) -> None:\n        text = skill_text().replace(\"description:\", \"metadata: owner\\ndescription:\")\n        report = validate_skill_text(text, \"release-check\")\n        self.assertIn(\"metadata-shape\", {issue.code for issue in report.issues})\n\n    def test_allowed_tools_must_be_non_empty_string(self) -> None:\n        text = skill_text().replace(\"description:\", \"allowed-tools:\\ndescription:\")\n        report = validate_skill_text(text, \"release-check\")\n        self.assertIn(\"allowed-tools-shape\", {issue.code for issue in report.issues})\n\n    def test_bundled_checker_parses_folded_description(self) -> None:\n        script_path = (\n            Path(__file__).resolve().parents[2]\n            / \"outputs\"\n            / \"skill-contract-reviewer\"\n            / \"scripts\"\n            / \"check_skill.py\"\n        )\n        spec = importlib.util.spec_from_file_location(\"bundled_checker\", script_path)\n        self.assertIsNotNone(spec)\n        self.assertIsNotNone(spec.loader)\n        module = importlib.util.module_from_spec(spec)\n        spec.loader.exec_module(module)\n        with tempfile.TemporaryDirectory() as temp_dir:\n            bundle = Path(temp_dir) / \"folded-skill\"\n            bundle.mkdir()\n            (bundle / \"SKILL.md\").write_text(\n                \"\"\"---\nname: folded-skill\ndescription: >\n  Review a package when release\n  evidence is required.\n---\nBody\n\"\"\",\n                encoding=\"utf-8\",\n            )\n            result = module.validate(bundle)\n        self.assertTrue(result[\"valid\"])\n        self.assertEqual(\n            result[\"description\"],\n            \"Review a package when release evidence is required.\",\n        )\n\n    def test_bundled_checker_validates_optional_core_fields(self) -> None:\n        script_path = (\n            Path(__file__).resolve().parents[2]\n            / \"outputs\"\n            / \"skill-contract-reviewer\"\n            / \"scripts\"\n            / \"check_skill.py\"\n        )\n        spec = importlib.util.spec_from_file_location(\"bundled_optional_checker\", script_path)\n        self.assertIsNotNone(spec)\n        self.assertIsNotNone(spec.loader)\n        module = importlib.util.module_from_spec(spec)\n        spec.loader.exec_module(module)\n        with tempfile.TemporaryDirectory() as temp_dir:\n            bundle = Path(temp_dir) / \"optional-fields\"\n            bundle.mkdir()\n            (bundle / \"SKILL.md\").write_text(\n                \"\"\"---\nname: optional-fields\ndescription: Validate optional fields when reviewing a package.\ncompatibility: Requires Python 3.13.\nmetadata:\n  owner: platform\nallowed-tools: Read\n---\nBody\n\"\"\",\n                encoding=\"utf-8\",\n            )\n            result = module.validate(bundle)\n        self.assertTrue(result[\"valid\"])\n\n    def test_bundled_checker_rejects_malformed_top_level_line(self) -> None:\n        script_path = (\n            Path(__file__).resolve().parents[2]\n            / \"outputs\"\n            / \"skill-contract-reviewer\"\n            / \"scripts\"\n            / \"check_skill.py\"\n        )\n        spec = importlib.util.spec_from_file_location(\"bundled_strict_checker\", script_path)\n        self.assertIsNotNone(spec)\n        self.assertIsNotNone(spec.loader)\n        module = importlib.util.module_from_spec(spec)\n        spec.loader.exec_module(module)\n        with tempfile.TemporaryDirectory() as temp_dir:\n            bundle = Path(temp_dir) / \"strict-skill\"\n            bundle.mkdir()\n            (bundle / \"SKILL.md\").write_text(\n                \"\"\"---\nname: strict-skill\nthis is not yaml\ndescription: Reject malformed frontmatter.\n---\nBody\n\"\"\",\n                encoding=\"utf-8\",\n            )\n            result = module.validate(bundle)\n        self.assertFalse(result[\"valid\"])\n        self.assertIn(\n            \"frontmatter-syntax\", {error[\"code\"] for error in result[\"errors\"]}\n        )\n\n\nclass DecisionModelTests(unittest.TestCase):\n    def test_one_off_task_stays_a_prompt(self) -> None:\n        self.assertEqual(select_primitives(TaskShape()), (\"prompt\",))\n\n    def test_repo_method_and_capability_compose(self) -> None:\n        shape = TaskShape(\n            repeatable_method=True,\n            repository_default=True,\n            external_capability=True,\n        )\n        self.assertEqual(\n            select_primitives(shape), (\"AGENTS.md\", \"Agent Skill\", \"MCP tool\")\n        )\n\n    def test_lifecycle_event_selects_hook(self) -> None:\n        self.assertEqual(\n            select_primitives(TaskShape(lifecycle_event=True)), (\"hook\",)\n        )\n\n    def test_deterministic_transformation_selects_ordinary_code(self) -> None:\n        self.assertEqual(\n            select_primitives(TaskShape(deterministic_logic=True)), (\"ordinary code\",)\n        )\n\n    def test_isolated_context_selects_subagent(self) -> None:\n        self.assertEqual(\n            select_primitives(TaskShape(isolated_delegation=True)), (\"subagent\",)\n        )\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"}],"figures":["figures-agent-skills.js"],"html":"<h2 id=\"learning-objectives\">Learning Objectives</h2>\n<ul>\n<li>Define an agent skill without confusing it with a prompt, repository instructions, a tool, a hook, a subagent, or a plugin.</li>\n<li>Read the portable <code>SKILL.md</code> contract and separate it from runtime-specific extensions.</li>\n<li>Explain discovery, selection, activation, resource loading, tool use, and verification as distinct lifecycle stages.</li>\n<li>Validate a skill package before a runtime places it in an agent&#x27;s catalog.</li>\n<li>Choose between a skill, MCP tool, hook, subagent, or ordinary code for a concrete task.</li>\n</ul>\n<h2 id=\"ten-minute-first-success\">Ten-Minute First Success</h2>\n<p>Do this before the long explanation. You will create a small skill, install\nthe complete reviewer bundle into a real agent host, invoke it, verify the\nresult, and remove it. This proves the lifecycle with an observable result.</p>\n<h3 id=\"preflight-for-the-real-host-lab\">Preflight for the real-host lab</h3>\n<p>The real-host checkpoint requires Node.js, <code>npx</code>, Python 3, one selected\nskill-capable host, and write access to the project or user scope you choose in\nthe installer. Verify the local commands first:</p>\n<pre class=\"code\" data-lang=\"bash\"><code>node --version\nnpx --version\npython3 --version</code></pre>\n<p>Decide which host and scope you will use before installation. If any\nrequirement is unavailable, read this lesson on the website or continue with\nthe manual package exercise below. That fallback teaches the contract, but it\ndoes not prove host discovery, invocation, bundled-script execution, or\nuninstall behavior. Keep those observations marked pending.</p>\n<h3 id=\"1-start-in-an-empty-working-directory\">1. Start in an empty working directory</h3>\n<p>Run these commands from any parent directory where you keep learning work:</p>\n<pre class=\"code\" data-lang=\"bash\"><code>mkdir -p agent-skills-first-run\ncd agent-skills-first-run\nTARGET_ROOT=&quot;$(pwd -P)&quot;\nprintf &#x27;TARGET_ROOT=%s\\n&#x27; &quot;$TARGET_ROOT&quot;\nls -A</code></pre>\n<p>The final command should print nothing. If it prints files, choose a different\nempty directory so the review has a clear boundary.</p>\n<p>Create a directory for your first skill:</p>\n<pre class=\"code\" data-lang=\"bash\"><code>mkdir -p my-first-skill</code></pre>\n<p>Create <code>my-first-skill/SKILL.md</code> with this content:</p>\n<pre class=\"code\" data-lang=\"markdown\"><code>---\nname: my-first-skill\ndescription: Turn rough meeting notes into a compact decision record when the user asks to capture a technical decision.\n---\n\n# Decision record\n\nExtract the decision, context, alternatives, owner, and next review date.\nIf the notes do not contain a decision, ask one clarifying question instead\nof inventing one.</code></pre>\n<p>Verify that you created the file in the intended directory:</p>\n<pre class=\"code\" data-lang=\"bash\"><code>test -f my-first-skill/SKILL.md</code></pre>\n<p>No output and exit code 0 means the file exists.</p>\n<h3 id=\"2-install-the-complete-reviewer-bundle\">2. Install the complete reviewer bundle</h3>\n<p>Stay in <code>agent-skills-first-run</code> and run:</p>\n<pre class=\"code\" data-lang=\"bash\"><code>npx skills add rohitg00/ai-engineering-from-scratch --skill skill-contract-reviewer --full-depth</code></pre>\n<p>Choose the agent host and scope you are using. The installer should list\n<code>skill-contract-reviewer</code> and the destination it wrote. <code>--full-depth</code> is\nrequired because this lesson&#x27;s skill is a nested bundle with references, a\nscript, and an asset.</p>\n<p>Set <code>SKILL_ROOT</code> to the absolute directory reported by the installer. It must\nbe the directory containing the installed <code>SKILL.md</code>, not the lesson source\ndirectory and not the current workspace:</p>\n<pre class=\"code\" data-lang=\"bash\"><code># Replace the placeholder with the destination printed by the installer.\nSKILL_ROOT=&quot;$(cd &quot;/absolute/path/to/skill-contract-reviewer&quot; &amp;&amp; pwd -P)&quot;\ntest -f &quot;$SKILL_ROOT/SKILL.md&quot;\nprintf &#x27;SKILL_ROOT=%s\\n&#x27; &quot;$SKILL_ROOT&quot;</code></pre>\n<p>If the agent session was already open, start a new session or use that host&#x27;s\nskill rescan command. Do not assume every host hot-reloads its catalog.</p>\n<h3 id=\"3-invoke-it-explicitly\">3. Invoke it explicitly</h3>\n<p>In the installed agent, with <code>agent-skills-first-run</code> as the working\ndirectory, use the syntax supported by that host:</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Host</th><th>Explicit invocation</th></tr></thead><tbody><tr><td>Codex</td><td><code>skill-contract-reviewer</code>, or choose it from <code>/skills</code>, then provide the review request</td></tr><tr><td>Claude Code</td><td><code>/skill-contract-reviewer</code> followed by the review request</td></tr><tr><td>Portable fallback</td><td><code>Use skill-contract-reviewer to review the target package.</code></td></tr></tbody></table></div>\n<p>Use the absolute values printed for <code>SKILL_ROOT</code> and <code>TARGET_ROOT</code> in the\nrequest. Require the host to expand them before execution and show the exact\nresolved command, not a command that depends on the process working directory:</p>\n<pre class=\"code\" data-lang=\"text\"><code>Use skill-contract-reviewer to review &lt;TARGET_ROOT&gt;/my-first-skill. The installed bundle root is &lt;SKILL_ROOT&gt;. Run python3 &lt;SKILL_ROOT&gt;/scripts/check_skill.py &lt;TARGET_ROOT&gt;/my-first-skill. Before running it, show the fully resolved argv. Return the validation report, selected primitives, and one sentence for each selection. Include the resolved script path, resolved target path, cwd, argv, and exit code as execution evidence.</code></pre>\n<p>The resolved command should have this shape, with no placeholders remaining:</p>\n<pre class=\"code\" data-lang=\"bash\"><code>python3 &quot;/absolute/install/path/skill-contract-reviewer/scripts/check_skill.py&quot; \\\n  &quot;/absolute/workspace/path/agent-skills-first-run/my-first-skill&quot;</code></pre>\n<p>A successful result has all three properties:</p>\n<ol>\n<li>The host finds <code>skill-contract-reviewer</code> by name.</li>\n<li>The reviewer reads the package contract and runs its bundled validator.</li>\n<li>The response contains a validation report with no structural error for the\nsample, plus a justified primitive selection.</li>\n</ol>\n<p>The execution evidence must also name the script path, target path, cwd, exact\nargument vector, and exit code. A fluent report without those fields does not\nprove that the installed companion script ran.</p>\n<p>If the host reports that the skill is unavailable, verify the install\ndestination, rescan or restart once, and retry the explicit request. Do not\nrewrite the skill description to hide an installation failure.</p>\n<h3 id=\"4-probe-implicit-selection\">4. Probe implicit selection</h3>\n<p>Start a fresh agent turn and enter the same task without naming the skill:</p>\n<pre class=\"code\" data-lang=\"text\"><code>Review &lt;TARGET_ROOT&gt;/my-first-skill as a reusable agent package and tell me whether its package contract is valid.</code></pre>\n<p>If the host exposes selected skills, record whether it chose\n<code>skill-contract-reviewer</code>. If the host does not expose routing, mark implicit\nselection as unverified. The explicit invocation is the portable fallback.</p>\n<h3 id=\"5-clean-up\">5. Clean up</h3>\n<p>Remove only the installed reviewer bundle:</p>\n<pre class=\"code\" data-lang=\"bash\"><code>npx skills remove skill-contract-reviewer</code></pre>\n<p>Select the same host and scope used during installation. After a rescan or new\nsession, an explicit request for <code>skill-contract-reviewer</code> should report that\nit is unavailable. Keep <code>my-first-skill</code> for the later lessons, or remove the\nlab directory after you finish the track.</p>\n<h2 id=\"the-problem\">The Problem</h2>\n<p>Suppose your team has a reliable release workflow. It finds merged changes, checks migration notes, updates the changelog, runs a packaging command, and produces a review checklist.</p>\n<p>Putting that workflow in one prompt makes it easy to paste and hard to operate. The prompt has no stable identity, no discovery rule, no resource boundary, no testable package shape, and no answer to basic questions: Who may invoke it? When should the model select it? Which scripts can it run? Which files are trusted? What survives when context is compacted?</p>\n<p>The opposite mistake is to treat every reusable instruction as a skill. Repository conventions, deterministic automation, external tools, event hooks, and delegated agents solve different problems. Packing all of them into <code>SKILL.md</code> produces a directory that looks portable while depending on one host&#x27;s undocumented behavior.</p>\n<p>The first engineering task is classification. Decide what the artifact is before you decide how to package it.</p>\n<h2 id=\"the-concept\">The Concept</h2>\n<h3 id=\"skills-encode-procedural-knowledge\">Skills encode procedural knowledge</h3>\n<p>An agent skill is a directory whose entry point is <code>SKILL.md</code>. The entry file contains YAML frontmatter followed by Markdown instructions. The directory can also contain references, scripts, and assets.</p>\n<div class=\"lesson-figure\" data-figure=\"skill-package-anatomy\"></div>\n<p>The directory, not the Markdown file alone, is the deployable unit. A copied <code>SKILL.md</code> with missing references is a broken package even if its frontmatter parses.</p>\n<h3 id=\"the-neighboring-abstractions\">The neighboring abstractions</h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Artifact</th><th>Primary job</th><th>Loaded or run when</th><th>What it should not impersonate</th></tr></thead><tbody><tr><td>Prompt</td><td>Shape one model interaction</td><td>Included by an application or user</td><td>A versioned package with resources</td></tr><tr><td>Repository instructions</td><td>Explain one codebase&#x27;s standing rules</td><td>A coding runtime enters that scope</td><td>A reusable task workflow</td></tr><tr><td>Agent skill</td><td>Supply reusable procedural knowledge</td><td>Explicit or implicit activation</td><td>A hard authorization boundary</td></tr><tr><td>MCP tool</td><td>Expose a typed remote capability</td><td>The model or application calls it</td><td>A detailed operating procedure</td></tr><tr><td>Hook</td><td>Run deterministic logic on an event</td><td>The declared event occurs</td><td>Probabilistic model routing</td></tr><tr><td>Subagent</td><td>Delegate work with separate context and state</td><td>An orchestrator creates or calls it</td><td>A static instruction bundle</td></tr><tr><td>Plugin</td><td>Distribute a larger runtime extension</td><td>The host installs or enables it</td><td>The portable skill contract itself</td></tr><tr><td>Learned skill library</td><td>Store behavior discovered through experience</td><td>A policy retrieves a prior program or trajectory</td><td>A standards-based <code>SKILL.md</code> package</td></tr></tbody></table></div>\n<p>A release skill can tell the agent how to inspect a release. An MCP server can expose the release registry. A hook can forbid direct pushes. A subagent can independently audit the candidate. These pieces compose because they keep different responsibilities.</p>\n<h3 id=\"the-word-skill-names-two-different-ideas\">The word &quot;skill&quot; names two different ideas</h3>\n<p>Research systems sometimes call a learned program, successful trajectory, or environment-specific policy fragment a skill. An agent can create these artifacts during exploration, retrieve them by task similarity, execute them, and revise the library from feedback. Phase 14 · 10 builds that kind of lifelong-learning library.</p>\n<p>An Agent Skill in this mini-track is different. It is an authored package with a declared filesystem contract, catalog metadata, progressive disclosure, runtime-mediated invocation, and host-controlled tools. It can be generated or improved by an agent, but learning is not required for the format.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Dimension</th><th>Agent Skill package</th><th>Learned skill library</th></tr></thead><tbody><tr><td>Primary unit</td><td><code>SKILL.md</code> directory</td><td>Program, policy, trajectory, or memory record</td></tr><tr><td>Creation</td><td>Authored, generated, or curated</td><td>Usually discovered from environment experience</td></tr><tr><td>Selection</td><td>Catalog description plus runtime policy</td><td>Retrieval or policy over task state</td></tr><tr><td>Execution</td><td>Model follows instructions and calls host tools</td><td>Environment runs a stored behavior or code artifact</td></tr><tr><td>Portability</td><td>Package contract can cross compatible hosts</td><td>Often tied to one environment and action space</td></tr><tr><td>Evaluation</td><td>Routing, artifact, safety, and host compatibility</td><td>Reward, success rate, transfer, and library growth</td></tr></tbody></table></div>\n<p>Both ideas package reusable competence. They should not share implementation claims merely because they share a name.</p>\n<h3 id=\"the-portable-core\">The portable core</h3>\n<p>The Agent Skills specification requires two frontmatter fields:</p>\n<pre class=\"code\" data-lang=\"yaml\"><code>---\nname: release-readiness\ndescription: Inspect a release candidate when the user asks whether a version is ready to publish.\n---</code></pre>\n<p><code>name</code> is the stable identifier. It must satisfy the specification&#x27;s naming rules and match the parent directory. <code>description</code> is both documentation and routing metadata. It should say what the skill does and when it applies.</p>\n<p>The portable optional fields are:</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Field</th><th>Purpose</th><th>Portability note</th></tr></thead><tbody><tr><td><code>license</code></td><td>State the terms for the package</td><td>Core specification</td></tr><tr><td><code>compatibility</code></td><td>State environmental requirements</td><td>Core specification</td></tr><tr><td><code>metadata</code></td><td>Carry string-valued extension data</td><td>Core specification</td></tr><tr><td><code>allowed-tools</code></td><td>Suggest pre-approved tools</td><td>Experimental; host support varies</td></tr></tbody></table></div>\n<p>The Markdown body holds the operational instructions. It should define the workflow, decision points, failure behavior, and direct paths to supporting resources.</p>\n<pre class=\"code\" data-lang=\"markdown\"><code># Release readiness\n\nUse this workflow for a release candidate, not for ordinary development builds.\n\n1. Read `references/release-policy.md`.\n2. Run `python3 scripts/inspect_release.py --format json`.\n3. Stop if the report contains a blocking failure.\n4. Produce the checklist from `assets/release-checklist.md`.\n5. Ask for approval before any publish or tag action.</code></pre>\n<h3 id=\"runtime-extensions-are-a-second-layer\">Runtime extensions are a second layer</h3>\n<p>Some hosts accept extra frontmatter or companion configuration. Those fields can be useful, but they are not automatically portable.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Behavior</th><th>Example host extension</th><th class=\"al-center\">Portable core?</th></tr></thead><tbody><tr><td>Hide a skill from model routing while keeping direct user invocation</td><td><code>disable-model-invocation</code></td><td class=\"al-center\">No</td></tr><tr><td>Hide a skill from the user&#x27;s command menu while allowing model routing</td><td><code>user-invocable</code></td><td class=\"al-center\">No</td></tr><tr><td>Show argument help in a command menu</td><td><code>argument-hint</code></td><td class=\"al-center\">No</td></tr><tr><td>Run the skill in delegated context</td><td><code>context</code>, <code>agent</code></td><td class=\"al-center\">No</td></tr><tr><td>Pin model or reasoning settings</td><td><code>model</code>, <code>effort</code></td><td class=\"al-center\">No</td></tr><tr><td>Register lifecycle automation</td><td><code>hooks</code></td><td class=\"al-center\">No</td></tr><tr><td>Disable implicit invocation in Codex</td><td><code>agents/openai.yaml</code> policy</td><td class=\"al-center\">No</td></tr></tbody></table></div>\n<p>Treat each extension as an adapter. Keep the core workflow valid without it, document the fallback, and test the host that consumes it. A runtime may ignore an unknown field, reject it, or preserve it without implementing the behavior.</p>\n<h3 id=\"frontmatter-is-executable-metadata\">Frontmatter is executable metadata</h3>\n<p>Metadata changes system behavior before the skill body is read.</p>\n<ul>\n<li>A malformed <code>name</code> can make discovery fail.</li>\n<li>A vague <code>description</code> can route the wrong requests.</li>\n<li>A human-only flag can remove the skill from the model&#x27;s catalog.</li>\n<li>A tool allowance can change whether a host asks for permission.</li>\n<li>A context setting can move execution into a separate agent session.</li>\n</ul>\n<p>Review frontmatter like configuration code. Validate it, version it, and include its behavior in evals.</p>\n<h3 id=\"the-skill-lifecycle\">The skill lifecycle</h3>\n<div class=\"lesson-figure\" data-figure=\"skill-runtime-lifecycle\"></div>\n<p>Each arrow is a boundary with its own failure modes.</p>\n<ol>\n<li><strong>Discovery</strong> finds possible packages in configured locations.</li>\n<li><strong>Validation</strong> rejects malformed or unsafe packages before catalog publication.</li>\n<li><strong>Cataloging</strong> exposes a compact <code>name</code> and <code>description</code>, not the full package.</li>\n<li><strong>Selection</strong> decides whether the skill is relevant.</li>\n<li><strong>Activation</strong> loads the body into model-visible context.</li>\n<li><strong>Disclosure</strong> reads references or assets only when a branch requires them.</li>\n<li><strong>Execution</strong> uses host tools under the host&#x27;s permission and isolation rules.</li>\n<li><strong>Verification</strong> checks the produced artifact independently of the model&#x27;s claim.</li>\n</ol>\n<p>Collapsing these stages causes bad mental models. A discovered skill is not active. An active skill is not authorized to do everything it describes. A permitted tool call is not proof that the result is correct.</p>\n<h3 id=\"skills-and-tools-are-orthogonal\">Skills and tools are orthogonal</h3>\n<p>MCP answers, &quot;Which capabilities can this application call, and what are their schemas?&quot; A skill answers, &quot;How should an agent approach this class of task?&quot;</p>\n<div class=\"lesson-figure\" data-figure=\"skill-tool-orthogonality\"></div>\n<p>The skill may name a tool, but the host owns the actual capability registry. If the tool is absent, the skill should state a fallback or fail clearly. It should never imply that naming a capability creates it.</p>\n<h3 id=\"skills-and-repository-instructions-are-different-scopes\">Skills and repository instructions are different scopes</h3>\n<p>Repository instructions describe the environment you are already in: commands, conventions, generated files, and boundaries. A skill provides reusable procedure for a task that may occur across many repositories.</p>\n<p>When both apply, the active user request and repository rules constrain the skill. A generic refactoring skill must not override a repository rule that forbids editing generated files.</p>\n<h3 id=\"skills-do-not-import-one-another\">Skills do not import one another</h3>\n<p>One skill can direct the agent to invoke another, but this is not a language-level import. The second skill still goes through runtime discovery, eligibility, activation, permissions, and context handling.</p>\n<p>Write cross-skill dependencies as observable workflow edges:</p>\n<pre class=\"code\" data-lang=\"markdown\"><code>After producing the candidate changelog, invoke the `release-risk-review` skill.\nPass the candidate path and require a blocking or non-blocking verdict.\nIf that skill is unavailable, stop and report the missing dependency.</code></pre>\n<p>This makes the dependency testable and gives the host a chance to enforce policy.</p>\n<h2 id=\"build-it\">Build It</h2>\n<p><code>code/main.py</code> implements a small standards-oriented validator and an artifact chooser. It stays stdlib-only so every rule is visible.</p>\n<p>The validator exposes:</p>\n<ul>\n<li><code>parse_frontmatter(text)</code> to separate metadata from the body.</li>\n<li><code>validate_skill_text(text, directory_name, allowed_runtime_extensions=())</code> to check required fields, naming, unknown extensions, body presence, and portable limits.</li>\n<li><code>ValidationIssue</code> and <code>SkillReport</code> to return structured evidence instead of one opaque boolean.</li>\n<li><code>FrontmatterSyntaxError</code> for input that cannot be interpreted safely.</li>\n</ul>\n<p>The chooser exposes <code>TaskShape</code> and <code>select_primitives(task)</code>. It maps a task&#x27;s needs to ordinary code, repository instructions, a skill, a hook, a subagent, or an MCP tool.</p>\n<p>Run the lab:</p>\n<pre class=\"code\" data-lang=\"bash\"><code>cd &quot;$(git rev-parse --show-toplevel)&quot;\ncd phases/13-tools-and-protocols/22-skills-and-agent-sdks\npython3 code/main.py\npython3 -m unittest discover -s code/tests -v</code></pre>\n<p>This command block requires a local clone and must start from anywhere inside\nthat clone so <code>git rev-parse --show-toplevel</code> can resolve the repository root.</p>\n<p>The demo prints JSON for one valid portable skill, one host-extended skill, one invalid package, and several task-shape decisions. Inspect the issue codes. A package validator should explain how to fix an artifact without guessing on the author&#x27;s behalf.</p>\n<h3 id=\"validation-order-matters\">Validation order matters</h3>\n<p>Validate cheap structural facts before deeper content rules:</p>\n<div class=\"lesson-figure\" data-figure=\"skill-validation-order\"></div>\n<p>This order prevents secondary errors from obscuring the first broken invariant.</p>\n<h2 id=\"use-it\">Use It</h2>\n<p>Before writing a skill, fill out this decision card:</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Question</th><th>If yes</th><th>Likely primitive</th></tr></thead><tbody><tr><td>Does this need reusable model judgment across several steps?</td><td>The procedure is stable but decisions vary</td><td>Skill</td></tr><tr><td>Must this happen every time an event fires?</td><td>Missing one execution is unacceptable</td><td>Hook or application code</td></tr><tr><td>Does the model need an external capability with typed inputs?</td><td>The operation lives outside model context</td><td>Tool or MCP server</td></tr><tr><td>Does the work need isolated context, state, or ownership?</td><td>A separate worker returns a bounded result</td><td>Subagent</td></tr><tr><td>Is this guidance specific to one repository?</td><td>It describes local commands and constraints</td><td>Repository instructions</td></tr><tr><td>Is one interaction enough?</td><td>No package lifecycle is needed</td><td>Prompt</td></tr></tbody></table></div>\n<p>Many production workflows use more than one row. The card prevents one artifact from pretending to provide every property.</p>\n<h2 id=\"ship-it\">Ship It</h2>\n<p>This lesson produces the <code>skill-contract-reviewer</code> bundle under <code>outputs/</code>. It contains:</p>\n<ul>\n<li>a portable <code>SKILL.md</code> that reviews a proposed skill package;</li>\n<li>reference checklists for the portable contract and primitive selection;</li>\n<li>a deterministic validation script;</li>\n<li>task-shape fixtures covering prompts, skills, tools, hooks, ordinary code, and subagents.</li>\n</ul>\n<p>Install the full bundle, not only its entry file:</p>\n<pre class=\"code\" data-lang=\"bash\"><code>cd &quot;$(git rev-parse --show-toplevel)&quot;\npython3 scripts/install_skills.py /tmp/aiefs-skills --phase 13 --type skill</code></pre>\n<p>The course installer reports each copied Phase 13 skill and writes\n<code>/tmp/aiefs-skills/manifest.json</code>. This clean destination checks package shape;\nthe first-success loop above checks discovery and invocation in a real host.</p>\n<p>The following lessons deepen each lifecycle stage. Lesson 24 builds discovery and progressive disclosure. Lesson 25 builds invocation policy and routing. Lesson 26 separates permissions from sandboxing. Lesson 27 turns the whole package into an evaluated release artifact.</p>\n<h2 id=\"exercises\">Exercises</h2>\n<ol>\n<li>Classify five workflows from your own team using <code>TaskShape</code>. Defend every case where you choose more than one primitive.</li>\n<li>Add boundary tests proving that a 500-character <code>compatibility</code> value passes and a 501-character value fails as a specification error.</li>\n<li>Add one runtime extension to the allowlist. Write a test proving the same file is still distinguishable from a portable-only skill.</li>\n<li>Split a 400-line prompt into <code>SKILL.md</code>, one reference, one script contract, and one output template. Keep every file responsible for one kind of information.</li>\n<li>Design a failure response for a skill that references an unavailable MCP tool. Do not silently substitute a tool with broader permissions.</li>\n<li>Review an existing skill and label every sentence as routing, procedure, policy, reference pointer, or output contract. Move anything that does not belong.</li>\n</ol>\n<h2 id=\"key-terms\">Key Terms</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Term</th><th>What people say</th><th>What it actually means</th></tr></thead><tbody><tr><td>Agent skill</td><td>&quot;A saved prompt&quot;</td><td>A discoverable directory of procedural instructions and optional resources</td></tr><tr><td>Portable core</td><td>&quot;Fields every runtime shares&quot;</td><td>The contract defined by the Agent Skills specification</td></tr><tr><td>Runtime extension</td><td>&quot;Extra frontmatter&quot;</td><td>Host-specific configuration whose behavior requires a compatible adapter</td></tr><tr><td>Activation</td><td>&quot;The skill ran&quot;</td><td>The skill body entered model-visible context; execution may come later</td></tr><tr><td>Skill dependency</td><td>&quot;Import another skill&quot;</td><td>A runtime-mediated invocation edge with availability and policy checks</td></tr><tr><td>Tool contract</td><td>&quot;A function schema&quot;</td><td>Inputs, outputs, permissions, side effects, errors, and evidence for a capability</td></tr></tbody></table></div>\n<h2 id=\"further-reading\">Further Reading</h2>\n<ul>\n<li><a href=\"https://agentskills.io/specification\" target=\"_blank\" rel=\"noopener\">Agent Skills specification</a> for the portable directory and frontmatter contract.</li>\n<li><a href=\"https://agentskills.io/skill-creation/best-practices\" target=\"_blank\" rel=\"noopener\">Agent Skills best practices</a> for scope, instructions, and resource organization.</li>\n<li><a href=\"https://learn.chatgpt.com/docs/build-skills\" target=\"_blank\" rel=\"noopener\">OpenAI: Build skills</a> for current Codex discovery and invocation behavior.</li>\n<li><a href=\"https://code.claude.com/docs/en/skills\" target=\"_blank\" rel=\"noopener\">Claude Code skills</a> for one runtime&#x27;s invocation, argument, tool, and delegated-context extensions.</li>\n</ul>","quiz":[{"correct":0,"options":["Put the review method in an Agent Skill and expose the API through an MCP tool","Replace the API with a longer user prompt","Put both the method and the API implementation in AGENTS.md","Use a lifecycle hook as the only source of review instructions"],"q":"A team has a reusable review method and an existing API that supplies pull request data. Which design assigns each concern to the right primitive according to the runtime policy?","stage":"pre","why":"A skill carries reusable procedural knowledge, while MCP exposes an external capability. They can compose. AGENTS.md is better for repository-wide defaults, and a hook responds to lifecycle events rather than replacing either layer."},{"correct":1,"options":["It guarantees every host supports the same invocation syntax","It gives discovery and packaging one stable identity instead of two conflicting names","It makes the Markdown heading render correctly","It allows the skill to bypass host permissions"],"q":"Why should a validator require the SKILL.md name to match its containing directory?","stage":"check","why":"Discovery tools frequently index a skill by both folder and frontmatter. Matching them prevents ambiguous catalog entries and broken installation paths. It does not grant authority or standardize a host's invocation UI."},{"correct":1,"options":["Move the field into the skill name","Treat it as a host extension and validate it only under an explicit host policy","The field silently becomes part of the core standard","Every runtime must implement it before loading the skill"],"q":"A SKILL.md contains a field that only one runtime understands. What is the portable interpretation?","stage":"check","why":"Portable core metadata and host runtime extensions are separate contracts. An adapter may recognize an extension, but a core validator should not claim that the field has universal semantics."},{"correct":3,"options":["An MCP resource","A one-shot prompt","A repository glossary","A lifecycle hook"],"q":"Which primitive best represents a check that must run after every tool call?","stage":"check","why":"The defining requirement is event timing, so a lifecycle hook is the right mechanism. A skill may explain a workflow and MCP may expose a capability, but neither inherently fires after each tool call."},{"correct":2,"options":["When an external service needs an authenticated API call","When a script needs to be executed outside the workspace jail","When conventions should apply throughout work in a repository","When instructions should load only for a rare specialist task"],"q":"When is AGENTS.md a better home than an Agent Skill?","stage":"post","why":"AGENTS.md communicates durable repository context such as build commands and coding conventions. Task-specific procedures fit skills, external operations fit tools, and no instruction file should be used to escape a sandbox."},{"correct":1,"options":["A universal slash command in every agent host","Discoverable procedural instructions, subject to the host runtime's policies","Permission to execute every bundled script","Automatic network access"],"q":"What does a valid Agent Skill grant by itself?","stage":"post","why":"The portable artifact supplies metadata and instructions. Discovery, invocation UI, tool access, approvals, and script execution remain runtime responsibilities, so validity is not equivalent to authority."}],"toc":[[2,"learning-objectives","Learning Objectives"],[2,"ten-minute-first-success","Ten-Minute First Success"],[3,"preflight-for-the-real-host-lab","Preflight for the real-host lab"],[3,"1-start-in-an-empty-working-directory","1. Start in an empty working directory"],[3,"2-install-the-complete-reviewer-bundle","2. Install the complete reviewer bundle"],[3,"3-invoke-it-explicitly","3. Invoke it explicitly"],[3,"4-probe-implicit-selection","4. Probe implicit selection"],[3,"5-clean-up","5. Clean up"],[2,"the-problem","The Problem"],[2,"the-concept","The Concept"],[3,"skills-encode-procedural-knowledge","Skills encode procedural knowledge"],[3,"the-neighboring-abstractions","The neighboring abstractions"],[3,"the-word-skill-names-two-different-ideas","The word \"skill\" names two different ideas"],[3,"the-portable-core","The portable core"],[3,"runtime-extensions-are-a-second-layer","Runtime extensions are a second layer"],[3,"frontmatter-is-executable-metadata","Frontmatter is executable metadata"],[3,"the-skill-lifecycle","The skill lifecycle"],[3,"skills-and-tools-are-orthogonal","Skills and tools are orthogonal"],[3,"skills-and-repository-instructions-are-different-scopes","Skills and repository instructions are different scopes"],[3,"skills-do-not-import-one-another","Skills do not import one another"],[2,"build-it","Build It"],[3,"validation-order-matters","Validation order matters"],[2,"use-it","Use It"],[2,"ship-it","Ship It"],[2,"exercises","Exercises"],[2,"key-terms","Key Terms"],[2,"further-reading","Further Reading"]]});
